-                .collect();
-        match states.as_slice() {
-            [one] => *counts.entry(*one).or_insert(0) += 1,
-            [] => problems.push(format!("`{id}` is in no state: bind it, declare it agent-only, or defer it")),
-            many => problems.push(format!("`{id}` is in several states: {many:?}")),
-        }
-    }
