-        }
-        if v["section"].as_str().is_none_or(str::is_empty) {
-            problems.push(format!("deferred `{id}`: no spec section (D-31)"));
-        }
-        if r.get(id).is_none() {
-            problems.push(format!("deferred `{id}` is not registered"));
-        }
-    }
-    (problems, counts)
-}
